solution:
def wait_time(status, headers):
    if status != 429:
        return 0
    h = {k.lower(): v for k, v in headers.items()}
    return int(h.get("retry-after", 1))

alt:
def wait_time(status, headers):
    if status == 429:
        for k, v in headers.items():
            if k.lower() == "retry-after":
                return int(v)
        return 1
    return 0
